// Each frozen mapped CLI product is paired with its own complete no-map build.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),assert=require('node:assert/strict'),{spawnSync}=require('node:child_process'),graph=require('./ge5_inputs.cjs');
function verify(compiler,observations){const root=path.resolve(__dirname,'../../../..'),input=require(root+'/backend/bluets/tests/fixtures/ge5_source_maps/cases.json'),parents=graph.parents(root,input),hash=graph.sha256(fs.readFileSync(compiler)),temporary=fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()),'ge5-replacement-nomap-')),verified=[],failures=[];assert.equal(observations.length,67);
 try{for(const row of observations){try{assert.equal(row.compilerSha256,hash);const original=graph.resolve(input,input.cases[row.index],parents);assert.equal(input.cases[row.index].form,'ge3_decorator_compositions/literal-replacement-order');const directory=path.join(temporary,String(row.index));for(const[name,text]of Object.entries(original.files)){const file=path.join(directory,name);fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,text);}const options={...original.options,sourceMap:false,inlineSourceMap:false,inlineSources:false};const removedJavaScriptSourceRoot=options.sourceRoot;let originalNoMapRejection=null;if(removedJavaScriptSourceRoot){const invalid=path.join(directory,'tsconfig-invalid.json');fs.writeFileSync(invalid,JSON.stringify({compilerOptions:options,files:[original.entry]}));const blue=spawnSync(compiler,['--project',invalid,'--diagnostics-json'],{encoding:'utf8',maxBuffer:16*1024*1024}),native=spawnSync(process.execPath,[require(root+'/backend/bluets/tests/fixtures/oracle_support/resolve_package.cjs')(process.env.BLUEICE_BLUETSC_ORACLE||'tsc','typescript','bin/tsc'),'--project',invalid,'--pretty','false'],{encoding:'utf8',maxBuffer:16*1024*1024});assert(!blue.error&&!native.error);assert.notEqual(blue.status,0);assert.notEqual(native.status,0);const diagnostics=blue.stderr.split(/\r?\n/).filter(Boolean).map(line=>JSON.parse(line));assert(diagnostics.some(d=>d.typescript?.code===5051&&/sourceRoot/.test(d.rawMessage)));assert(/TS5051/.test(native.stdout+native.stderr)&&/sourceRoot/.test(native.stdout+native.stderr));originalNoMapRejection={blue:{status:blue.status,diagnostics},native:{status:native.status,stdout:native.stdout,stderr:native.stderr}};}delete options.sourceRoot;fs.writeFileSync(path.join(directory,'tsconfig.json'),JSON.stringify({compilerOptions:options,files:[original.entry]}));const run=spawnSync(compiler,['--project',path.join(directory,'tsconfig.json'),'--diagnostics-json','--listFiles'],{encoding:'utf8',maxBuffer:16*1024*1024});assert(!run.error);assert.equal(run.status,0);assert.deepEqual(run.stderr.split(/\r?\n/).filter(Boolean).map(line=>JSON.parse(line)),[]);const selected=[...new Set(run.stdout.split(/\r?\n/).filter(Boolean).map(name=>path.relative(directory,name).replace(/\\/g,'/')).filter(name=>Object.hasOwn(original.files,name)))].sort();assert.deepEqual(selected,Object.keys(original.files).filter(name=>/\.tsx?$/.test(name)).sort(),'unchanged complete source selection');const pairs=[];for(const[name,mapped]of Object.entries(row.outputs)){if(!/\.(?:js|cjs|mjs)$/.test(name))continue;const raw=fs.readFileSync(path.join(directory,name),'utf8'),position=mapped.lastIndexOf('\n//# sourceMappingURL=');assert(position>=0);const body=mapped.slice(0,position);assert.equal(raw,body,'exact mapped/no-map JavaScript body bytes '+row.index+'/'+name);pairs.push({file:name,sha256:graph.sha256(raw),bytes:Buffer.byteLength(raw)});}assert.equal(pairs.length,1);for(const[name,mapped]of Object.entries(row.outputs))if(/\.d\.(?:ts|mts|cts)(?:\.map)?$/.test(name)){const text=fs.readFileSync(path.join(directory,name),'utf8');if(removedJavaScriptSourceRoot&&name.endsWith('.map')){const expected=JSON.parse(mapped),observed=JSON.parse(text);assert.equal(observed.sourceRoot,'');assert.equal(observed.sources.length,1);assert.equal(path.resolve(directory,options.mapRoot||path.dirname(name),observed.sources[0]),path.resolve(directory,original.entry),'declaration no-map source layout resolves to the exact original entry');assert.deepEqual(observed,{...expected,sourceRoot:'',sources:observed.sources},'only the required removal of JavaScript sourceRoot changes declaration-map layout');}else assert.equal(text,mapped,'raw declaration/map unchanged without JavaScript maps');}verified.push({index:row.index,pairs,...(removedJavaScriptSourceRoot?{originalConfigurationRejected:true,originalNoMapRejection,removedJavaScriptSourceRoot,reason:'sourceRoot requires JavaScript source maps; declaration-map coordinates are unchanged and its projected source resolves to this exact input'}:{})});}catch(error){failures.push({index:row.index,error:error.message,stack:error.stack});}}}finally{fs.rmSync(temporary,{recursive:true,force:true});}assert.equal(graph.sha256(fs.readFileSync(compiler)),hash);return{configurations:observations.length,mapNoMapBytePairs:verified.filter(r=>!r.originalConfigurationRejected).length,expectedRejectedConfigurations:verified.filter(r=>r.originalConfigurationRejected).map(r=>r.index),supplementalProjectedBytePairs:verified.filter(r=>r.originalConfigurationRejected).length,scope:'66 legal no-map configurations plus the unchanged invalid sourceRoot rejection and its separately recorded legal projection',verified,failures,compilerSha256:hash,completeFamily:failures.length===0};}
module.exports={verify};if(require.main===module){const report=verify(process.argv[2],JSON.parse(fs.readFileSync(0,'utf8')));console.log(JSON.stringify(report,null,2));if(report.failures.length)process.exitCode=1;}
